package com.jian.scrcpy.media;import javax.sound.sampled.*;
public final class JavaSoundPlayer implements AutoCloseable{private SourceDataLine line;public synchronized void open(int rate,int channels)throws LineUnavailableException{if(line!=null)return;var f=new AudioFormat(AudioFormat.Encoding.PCM_SIGNED,rate,16,channels,channels*2,rate,false);line=AudioSystem.getSourceDataLine(f);line.open(f,Math.max(4096,rate*channels/10));line.start();}public synchronized void write(byte[] pcm){if(line!=null)line.write(pcm,0,pcm.length);}public synchronized void close(){if(line!=null){line.drain();line.stop();line.close();line=null;}}}